Import ListNotations.
Open Scope Z_scope.
Notation mem := (word -> option byte).

(* [comment removed for export] *)
Definition rb (SB c : Z) : Z := SB + c * 2^32.                  (* [comment removed for export] *)
Definition fa (SB c : Z) : Z := rb SB c + 0xE0000000.           (* [comment removed for export] *)
Definition RIS_of (SB : Z) : Z := SB + 2^37.
Definition rinfo (RIS c : Z) : Z := RIS + 128 * c.
Definition zw (z : Z) : word := Z_to_bv 64 z.
Definition cp_ok (z : Z) : Prop := 0 <= z < 2^28.

(* [comment removed for export] *)
(* [comment removed for export] *)
Definition inst_cells (SB : Z) (m : mem) : Prop :=
  rw_cells asegs m i_spacebeg [C8 (Z_to_bv 64 SB); C8 (Z_to_bv 64 0xffffffff); C8 (Z_to_bv 64 (RIS_of SB))]
  /\ rw_cells asegs m i_premapped [C1 (Z_to_bv 8 0)].
(* [comment removed for export] *)
Definition mm_gcells (m : mem) : Prop :=
  rw_cells asegs m 0x225d00 [C8 (Z_to_bv 64 0x2d4560)]
  /\ rw_cells asegs m 0x225d10 [C8 (Z_to_bv 64 0x2d65e8)]
  /\ rw_cells asegs m 0x2d4560 [C8 (Z_to_bv 64 4096)]
  /\ rw_cells asegs m 0x2d6678 [C8 (Z_to_bv 64 0)]
  /\ rw_cells asegs m 0x2d66ec [C1 (Z_to_bv 8 0)].
(* [comment removed for export] *)
Definition ri_lock (m : mem) (R lk : Z) : Prop := rw_cells asegs m R [C8 (Z_to_bv 64 lk)].
Definition ri_core (m : mem) (R nfree mfa auser muser : Z) : Prop :=
  rw_cells asegs m (R + 16) [C8 (Z_to_bv 64 nfree); C8 (Z_to_bv 64 mfa); C8 (Z_to_bv 64 auser); C8 (Z_to_bv 64 0);
                             C8 (Z_to_bv 64 muser); C8 (Z_to_bv 64 0)].
Definition ri_tail (m : mem) (R : Z) (rand : word) (exh : byte) (pad : list byte) (nalloc nfreed r0 r1 r2 r3 : Z) : Prop :=
  rw_cells asegs m (R + 64) [C4 rand; C1 exh; CB 3 pad; C8 (Z_to_bv 64 nalloc); C8 (Z_to_bv 64 nfreed);
                             C8 (Z_to_bv 64 r0); C8 (Z_to_bv 64 r1); C8 (Z_to_bv 64 r2); C8 (Z_to_bv 64 r3)].
(* [comment removed for export] *)
Definition fl_arr (m : mem) (SB c : Z) (ws : list word) : Prop := u32arr asegs m (fa SB c) ws.

(* [comment removed for export] *)
Definition round_fa (x : Z) : Z := ((x + 0x3ffff) / 0x40000) * 0x40000.

