Definition poison_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (a n lo : Z) (m : mem) (PC : mem -> Prop) : machine_state -> Prop :=
  fun ms' => exists (t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0' t1' t2' s0 s1 a0' a1' a2' a3' a4' a5' a6' a7' s2 s3 s4 s5 s6 s7 s8 s9 s10 s11
                  t3' t4' t5' t6') F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(shad a, shad a + n / 8); (bv_unsigned sp - 64, bv_unsigned sp)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ rw_cells asegs m' (shad a) [CB (Z.to_nat (n / 8)) (repeat (Z_to_bv 8 250) (Z.to_nat (n / 8)))]
    /\ stk asegs m' lo (bv_unsigned sp) /\ PC m'.

(* [comment removed for export] *)
Definition poison_stmt (PC : mem -> Prop) : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (a n lo : Z) (shj : list byte),
  a mod 8 = 0 -> n mod 8 = 0 -> 0 < n -> kHighShadowEnd < a -> a + n <= 2^47 ->
  rw_cells asegs m (shad a) [CB (Z.to_nat (n / 8)) shj] ->
  PC m ->
  stk asegs m lo (bv_unsigned sp) -> kHighShadowEnd + 8 <= lo -> lo <= bv_unsigned sp - 64 -> bv_unsigned sp <= 2^47 ->
  mem_inv asegs m ->
  evt asegs (poison_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc a n lo m PC)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 a) (Z_to_bv 64 n) (Z_to_bv 64 250) a3 a4 a5 a6 a7
             s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 poison_entry) fc None m (seg_rom asegs)).

(* [comment removed for export] *)
Definition PC_framed (PC : mem -> Prop) : Prop :=
  forall m m' W, PC m -> munch W m m' -> wmono asegs m m' -> disjoint_from W img_hull_lo (img_hull_hi - img_hull_lo) -> PC m'.

